def find_evens(nums):
    res = []
    for x in nums:
        if x % 2 == 0:
            res.append(x)
    return res

def binary_search(arr, target):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

